INSERT INTO `tugas` (`id`, `id_matkul`, `tgl`, `tgl_deadline`, `judul_tugas`, `deskripsi`, `jawaban`, `kategori`, `tipe`, `status`, `created_at`, `updated_at`) VALUES
(1, '1', '2024-08-28', '2024-09-02', 'Instruksi Tugas Buku Peserta PKKP 2024', '<p>Instruksi Tugas Buku</p><ol><li><p>Buku Peserta PKKP 2024 berukuran A5.</p></li><li><p>Berisikan <b>50 Lembar kertas A5 (Potrait, 148 mm x 210 mm) </b>polos.</p></li><li><p>Download&nbsp;<a href=\"https://drive.google.com/drive/folders/1-9ElSyuRJhlmDubZzBpuXwKB5YL7AA7E\" target=\"_blank\">Cover Depan &amp; Belakang</a> pada link yang akan diberikan oleh panitia.</p></li><li><p>Pengisian nama, NIM dan lainnya dapat dilakukan secara digital, <b>tidak boleh pakai tulisan tangan</b>. Bisa menggunakan aplikasi editing foto di android atau pc/mac. Untuk <b>font textnya menggunakan Arial</b> dengan ukuran yang menyesuaikan.</p></li><li><p>Kemudian Print cover depan &amp; belakang dengan <b>kertas buffalo berwarna putih</b>, dan cover depan &amp; belakangnya dilapisi dengan <b>mika bening</b> (agar tidak kotor, basah, dll).</p></li><li><p>Isi Buku Peserta PKKP 2024 <b>wajib ditulis tangan, rapih, dan jelas</b>.</p></li><li><p>Penulisan <b>menggunakan pulpen berwarna hitam</b> dan <b>dilarang menggunakan pensil.</b></p></li><li><p>Total ada 52 lembar di dalam Buku Peserta PKKP 2024 (Cover Depan, 50 Lembar kertas putih A5, Cover Belakang).</p></li><li><p>Setelah itu, jilid spiral berwarna putih Buku Peserta PKKP 2024.</p></li></ol><p><img src=\"/storage/files/images/isi_buku_peserta_1724901576.jpeg\" class=\"img-fluid\" style=\"width: 1080px;\"></p><p><br></p><p>Link Detail:&nbsp;<a href=\"https://s.pnj.ac.id/BukuDanNameTagPesertaPKKP2024\" target=\"_blank\">FILE DRIVE</a>&nbsp;<a href=\"https://www.instagram.com/p/C_NyyDizPez/?img_index=1\" target=\"_blank\">INSTAGRAM</a></p><p></p>', '<p><img style=\"width: 428px;\" src=\"/storage/files/images/WhatsApp_Image_2024-08-29_at_16.30.08_1724923825.jpeg\" class=\"img-fluid\"><br></p>', 'PKKP', 'Kuliah', 'Selesai', '2024-08-28 16:06:47', '2024-08-31 13:59:22'),
(2, '1', '2024-08-28', '2024-09-02', 'Instruksi Nametag PKKP 2024', '<p>Instruksi Tugas Nametag PKKP 2024</p><ol><li><p>Download soft file name tag dari link yang akan diberikan, kemudian isi sesuai data diri peserta masing masing.</p></li><li><p>Pengisian nama, nim dan lainnya dapat dilakukan secara digital, tidak boleh pakai tulisan tangan. bisa menggunakan aplikasi editing foto di android ataupun pc/mac. untuk font textnya menggunakan Arial dengan ukuran yang menyesuaikan.</p></li><li><p>Pengisian pas foto formal dilakukan secara digital dan untuk ukurannya menyesuaikan dengan frame/bingkai yang sudah disediakan di desain.</p></li><li><p>Jika dirasa sudah benar. Print Name tag dengan kertas ukuran A5 (kertas buffalo)</p></li><li><p>Setelah di print, laminating name tag (agar tidak basah dan lecek)</p></li><li><p>Berikan 2 bolongan diatas (kanan &amp; kiri) untuk dipasangkan tali kur.</p></li><li><p>Panjang tali kur menyesuaikan badan Peserta PKKP 2024</p></li><li><p>Warna tali kur menyesuaikan jurusan masing-masing:</p><ul style=\"list-style-type: disc;\"><li><p>Adm. Niaga: Abu-abu muda</p></li><li><p>Akuntansi: Merah Tua</p></li><li><p><b>Elektro:&nbsp;<span style=\"letter-spacing: 0.05em;\">Biru tua</span></b></p></li><li><p>Sipil:&nbsp;<span style=\"letter-spacing: 0.05em;\">Coklat Muda</span></p></li><li>Mesin: Hitam</li><li>TIK: Putih</li><li>TGP: Ungu muda</li></ul></li></ol><p><ul style=\"list-style-type: disc;\"></ul></p><p>Link Detail:&nbsp;<a href=\"https://s.pnj.ac.id/BukuDanNameTagPesertaPKKP2024\" target=\"_blank\">FILE DRIVE</a>&nbsp;<a href=\"https://www.instagram.com/p/C_NyehizfyC/?img_index=1\" target=\"_blank\">INSTAGRAM</a></p><p></p>', '<p><img style=\"width: 428px;\" src=\"/storage/files/images/WhatsApp_Image_2024-08-29_at_16.26.45_1724923623.jpeg\" class=\"img-fluid\"><br></p>', 'PKKP', 'Kuliah', 'Selesai', '2024-08-28 16:59:11', '2024-08-31 13:55:45'),
(3, '1', '2024-08-29', '2024-09-01', 'Tugas Individual I (Video Pengenalan)', '<p>Creative Introduction of New Faces PKKP 2024</p><ol><li><p>Penugasan WAJIB bersifat individu&nbsp;</p></li><li><p>Peserta WAJIB membuat video perkenalan secara kreatif dengan minimal durasi 1 menit, dengan menyertakan :&nbsp;&nbsp;</p><ul style=\"list-style-type: disc;\"><li><p>Nama, Jurusan, Angkatan, Prodi, Gugus, Asal Sekolah, Hobi, Domisili\n(WAJIB disebutkan sambil bernyanyi dengan lagu yang tidak ditentukan/bebas)</p><p>Contoh :</p><p><a href=\"https://vt.tiktok.com/ZS26mqGTo/\" target=\"_blank\">Contoh 1</a>&nbsp;&nbsp;</p><p><a href=\"https://vt.tiktok.com/ZS26mt7oj/\" target=\"_blank\">Contoh 2</a><br></p></li><li><p>Seberapa tau kamu tentang kampus kamu&nbsp;</p></li><li><p>Alasan memilih jurusan / prodi tersebut&nbsp;</p></li><li><p>Harapan / Cita cita setelah memilih jurusan / prodi tersebut&nbsp;</p></li><li><p>Kontribusi kalian sebagai mahasiswa&nbsp;</p></li><li><p>Harapan untuk PNJ&nbsp;</p></li><li><p>Menceritakan sedikit tentang pulau sesuai gugus masing-masing&nbsp;</p></li></ul></li><li><p>Ketentuan Peserta :&nbsp;</p><ul style=\"list-style-type: disc;\"><li><p>Harus terlihat wajahnya&nbsp;</p></li><li><p>Memakai kemeja putih&nbsp;</p></li><li><p>Bagi laki-laki memakai celana hitam&nbsp;</p></li><li><p>Bagi perempuan memakai rok hitam dan kerudung hitam (bagi yang menggunakan hijab)&nbsp;</p></li><li><p>Rambut rapi&nbsp;</p></li></ul></li><li><p>Video di posting di TikTok dan Reels Instagram First Account dan akun tidak boleh privat&nbsp;&nbsp;</p></li><li><p>Wajib untuk tag akun Instagram @pkkp_pnj @politekniknegerijakarta dan TikTok @pkkp_pnj @pnjofficial_&nbsp;</p></li><li><p>Peserta dilarang menghapus video tersebut sampai tanggal 10 September 2024&nbsp;</p></li><li><p>Caption :&nbsp;&nbsp;</p><p>Isi caption sekreatif mungkin dengan tambahan tagar #PKKP2024 #BerdayaUntukNegeriBerkaryaUntukMasaDepan #PoliteknikNegeriJakarta #JurusanKalian #NamaGugus&nbsp;</p></li></ol><p><b>Tujuan &amp; Manfaat :</b></p><ul><li><p>Melatih public speaking dan kreatifitas&nbsp;</p></li><li><p>Saling mengenal satu sama lain antar mahasiswa baru&nbsp;</p></li><li><p>Meramaikan pembukaan rangkaian acara PKKP 2024 ke khalayak umum&nbsp;</p></li><li><p>Meningkatkan rasa kebanggaan terhadap kampus Politeknik Negeri Jakarta&nbsp;</p></li></ul><p style=\"line-height: 1;\"><b><br></b></p><p><b>DEADLINE PENGUMPULAN : 1 SEPTEMBER 2024 PUKUL 22.00 WIB&nbsp;</b></p><p><br></p><p>Link Detail:&nbsp;<a href=\"https://s.pnj.ac.id/MissionCreativeIntroduction\" target=\"_blank\">FILE DRIVE</a>&nbsp;<a href=\"https://www.instagram.com/p/C_Nm42NTRmB/?img_index=1\" target=\"_blank\">INSTAGRAM</a></p><p>LINK PENGUMPULAN :&nbsp;<a href=\"https://s.pnj.ac.id/PengumpulanMissionCreativeIntroduction\" target=\"_blank\">https://s.pnj.ac.id/PengumpulanMissionCreativeIntroduction</a></p>', '<p><img src=\"/storage/files/images/Tugas_Introduction_Faces_PKKP_2024_Instagram_1725011227.jpeg\" class=\"img-fluid\" style=\"width: 902px;\"><img src=\"/storage/files/images/Tugas_Introduction_Faces_PKKP_2024_Tiktok_1725011237.jpeg\" class=\"img-fluid\" style=\"width: 734px;\"><br></p>', 'PKKP', 'Kuliah', 'Selesai', '2024-08-28 17:09:23', '2024-08-31 14:01:35'),
(4, '1', '2024-08-29', '2024-09-02', 'Tugas Buku SOSJUR 2024', '<p>[ MISSION OF GEBYAR ORMAWA ]</p><p>Hallo Sahabat Elektro 2024! 👋🏻</p><p>Kita ada info terbaru nih mengenai Mission of Gebyar Ormawa yang dimana wajib bagi seluruh mahasiswa baru 🤗</p><p>Yuk disimak infonya dengan baik!</p><p>➖➖➖➖➖➖➖➖➖</p><p>Buku Tulis Ukuran : <b>B5</b></p><p>Sampul berwarna <b>\"Biru Dongker\"</b> dengan jenis <b>kertas asturo</b>❗</p><p><br></p><p><b>📌 COVER</b></p><ul><li><p>Foto formal <b>2R</b> dengan <b>Background Merah</b></p></li><li><p>Untuk label nama <b>berukuran 13 cm × 9 cm</b> dengan warna: <b>KUNING</b></p></li></ul><p><b>📌 ISI BUKU</b></p><p><br></p><p><b>HALAMAN 1 :&nbsp;</b></p><p>Logo Himpunan Mahasiswa Elektro Politeknik Negeri Jakarta, <b>digambar tangan berwarna</b>, <b>diwarnai menggunakan spidol</b>.</p><p><b>Note</b> : <b>Beri jeda 3 baris pada atas dan bawah buku</b>❗</p><p><br></p><p><b>HALAMAN 3 :&nbsp;</b></p><p>BIODATA DIRI dengan format sebagai berikut :</p><ol><li><p>Nama Lengkap: Fahmi Ibrahim</p></li><li><p>Nama Panggilan: Fahmi</p></li><li><p>Program Studi: D3 - Teknik Elektronika Industri</p></li><li><p>Tempat, tanggal, lahir: Jakarta, 24 November 2004</p></li><li><p>Agama: Islam</p></li><li><p>Asal Sekolah (SMA/SMK): SMKN 5 Jakarta</p></li><li><p>Alamat Rumah/Kos: Jl. Cipinang Muara III No. 33, RT.002/RW.011 Kel. Cipinang Muara, Kec. Jatinegara, 13420</p></li><li><p>No. HP: 0856-9125-3593</p></li><li><p>Motivasi Masuk Jurusan Teknik Elektro PNJ ( ceritakan ) :</p></li></ol><p style=\"line-height: 1;\"><br></p><p><b>HALAMAN 5 :</b></p><p>Organigram Struktural Jurusan Teknik Elektro (LANDSCAPE)\nLINK CONTOH FORMAT ORGANIGRAM STRUKTURAL :&nbsp;</p><p><a href=\"https://bit.ly/BaganStruktural\" target=\"_blank\">https://bit.ly/BaganStruktural</a><br></p><p>Note : Pada saat Sosialisasi Jurusan❗</p><p><br></p><p><b>HALAMAN 7 :&nbsp;</b></p><p>VISI DAN MISI PROGRAM STUDI KALIAN (WAJIB DIHAFALKAN)</p><p>LINK VISI MISI PROGRAM STUDI :</p><p><a href=\"https://bit.ly/Visi-MisiProdi-TE\" target=\"_blank\">https://bit.ly/Visi-MisiProdi-TE</a><br></p><p><br></p><p><b>HALAMAN 9 :&nbsp;</b></p><p>Tuliskan dan jelaskan Sumpah Mahasiswa, 5 fungsi Mahasiswa dan Tri Dharma Perguruan Tinggi❗</p><p><br></p><p><b>HALAMAN 11 :</b></p><p>Lirik lagu kemahasiswaan, diantara lain :</p><ol><li><p>Totalitas Perjuangan</p></li><li><p>Darah Juang&nbsp;</p></li><li><p>Buruh Tani&nbsp;</p></li></ol><p style=\"line-height: 1;\"><br></p><p><b>HALAMAN 13  :&nbsp;</b></p><p>Tuliskan tentang KSM di Jurusan Teknik Elektro</p><p>Note : Pada saat Sosialisasi Jurusan❗</p><p><br></p><p><b>HALAMAN 15 :&nbsp;</b></p><p>Lirik lagu-lagu Elektro</p><p><br></p><p>Link Lirik lagu lagu elektro:</p><p><a href=\"https://bit.ly/LAGUTEKNIKELEKTRO\" target=\"_blank\">https://bit.ly/LAGUTEKNIKELEKTRO</a><br></p><p><br></p><p><b>HALAMAN 17 :&nbsp;</b></p><p>Target yang ingin dicapai sebagai :</p><ol><li><p>Mahasiswa Teknik Elektro</p></li><li><p>Mahasiswa PNJ</p></li><li><p>Di Kehidupan</p></li></ol><p><br></p><p><b>📌 NOTE</b></p><p>‼️MISI INI BERSIFAT WAJIB BAGI SEMUA MAHASISWA BARU TEKNIK ELEKTRO PNJ 2024‼️</p><p><br></p><p>Contoh Gambar:</p><p><img src=\"/storage/files/images/sojur_1724866154.jpeg\" class=\"img-fluid\" style=\"width: 100%;\"><br></p><p><br></p><p>Follow &amp; Stay tune in our Socmed:</p><p>📣 LINE@ : @txe4371e (with @)</p><p>🎼Tiktok : @hme_pnj</p><p>📲 Instagram : @hme_pnj</p><p>🎬 Youtube : HME PNJ</p><p>🎙 Podcast : HME PNJ</p><p><br></p><p>➖➖➖➖➖➖➖➖➖➖➖➖\n</p><p>Departemen Kominfo 📡\n</p><p>HME PNJ 2023/2024\n</p><p>Dharma Sangga\n</p><p>#SatuKomandoSatukanElektro</p>', '<p><img src=\"/storage/files/images/WhatsApp_Image_2024-08-30_at_16.56.12_1725011825.jpeg\" class=\"img-fluid\" style=\"width: 1898px;\"><img src=\"/storage/files/images/WhatsApp_Image_2024-08-30_at_16.56.11_1725011849.jpeg\" class=\"img-fluid\" style=\"width: 1898px;\"><img src=\"/storage/files/images/WhatsApp_Image_2024-08-30_at_16.56.11_(1)_1725011868.jpeg\" class=\"img-fluid\" style=\"width: 1898px;\"><img src=\"/storage/files/images/WhatsApp_Image_2024-08-30_at_16.56.11_(2)_1725011885.jpeg\" class=\"img-fluid\" style=\"width: 1898px;\"><img src=\"/storage/files/images/WhatsApp_Image_2024-08-30_at_16.56.10_1725011935.jpeg\" class=\"img-fluid\" style=\"width: 1898px;\"><img src=\"/storage/files/images/WhatsApp_Image_2024-08-30_at_16.56.06_1725011970.jpeg\" class=\"img-fluid\" style=\"width: 1898px;\"><img src=\"/storage/files/images/WhatsApp_Image_2024-08-30_at_16.56.07_1725012010.jpeg\" class=\"img-fluid\" style=\"width: 1898px;\"><img src=\"/storage/files/images/WhatsApp_Image_2024-08-30_at_16.56.08_1725012043.jpeg\" class=\"img-fluid\" style=\"width: 1898px;\"><img src=\"/storage/files/images/WhatsApp_Image_2024-08-30_at_16.56.08_(1)_1725012064.jpeg\" class=\"img-fluid\" style=\"width: 1898px;\"><img src=\"/storage/files/images/WhatsApp_Image_2024-08-30_at_16.56.09_1725012086.jpeg\" class=\"img-fluid\" style=\"width: 1898px;\"><img src=\"/storage/files/images/WhatsApp_Image_2024-08-30_at_16.56.09_(1)_1725012103.jpeg\" class=\"img-fluid\" style=\"width: 1898px;\"><br></p>', 'PKKP', 'Kuliah', 'Selesai', '2024-08-28 17:14:47', '2024-08-31 13:49:40'),
(5, '1', '2024-08-30', '2024-09-02', 'Tugas Buku Kuning PKKP 2024', '<p>[Peraturan Pendidikan Politeknik Negeri Jakarta]</p><p><br></p><p>\n\nHalo kawan PNJ!👋🏻\n</p><p>\nYuk perhatikan dan lakukan intruksi diatas ini😉.</p><p>\nPastikan kamu mengunduh, mencetak serta membaca Peraturan Pendidikan Politeknik Negeri Jakarta✨!.</p><p>\nUntuk kamu yang ingin mengetahui informasi lebih lanjut terkait PKKP 2024, follow semua sosial media kami💖\n\nSee you🤗</p><p><br></p><p>Link Detail:&nbsp;<a href=\"https://s.pnj.ac.id/PeraturanPendidikanPNJ\" target=\"_blank\">FILE DRIVE</a>&nbsp;<a href=\"https://www.instagram.com/p/C_J6NRgz-EN/?img_index=1\" target=\"_blank\">INSTAGRAM</a><br></p>', '<p><img src=\"/storage/files/images/WhatsApp_Image_2024-08-30_at_17.03.03_1725012207.jpeg\" class=\"img-fluid\" style=\"width: 1898px;\"><img src=\"/storage/files/images/WhatsApp_Image_2024-08-30_at_17.03.03_(1)_1725012212.jpeg\" class=\"img-fluid\" style=\"width: 1898px;\"><br></p>', 'PKKP', 'Kuliah', 'Selesai', '2024-08-30 09:41:18', '2024-08-31 13:57:21'),
(6, '1', '2024-08-30', '2024-09-01', 'Tugas Twibbon', '<p>[TWIBBON PESERTA PKKP 2024]</p><p><br></p><p>\nHalo peserta PKKP 2024 👋🏻\n</p><p>\nSiapkah kalian untuk mengikuti PKKP 2024?🤔\n</p><p>\nDalam rangka memenuhi salah satu tugas PKKP 2024, diwajibkan bagi seluruh peserta PKKP 2024 untuk mengupload twibbon di instagram pribadi masing masing\n</p><p><br></p><p>\n❗️KETENTUAN ❗️\n</p><p>1. Akun instagram tidak diprivate dan menandai akun instagram @politekniknegerijakarta, @pkkp_pnj @bempnj, serta menyebut akun instagram PJG masing-masing di caption.\n</p><p>2. Menggunakan foto sendiri dan tidak menggunakan foto bersama\n</p><p>3. ⁠Wajah harus terlihat jelas (tidak diperkenankan menggunakan masker dan memakai filter penutup wajah)\n</p><p>4. ⁠Berpakaian sopan dan tidak menggunakan atribut kelompok\n</p><p>5. ⁠Foto tidak mengandung unsur SARA dan penghinaan\n</p><p>6.⁠Twibbon dan Ketentuan dapat diakses pada link berikut :&nbsp;<a href=\"https://s.pnj.ac.id/TwibbonDanKetentuan\" target=\"_blank\">KLIK DISINI</a></p><p>7. Pengunggahan twibbon pada e-learning\n</p><p>8. Batas waktu pengunggahan twibbon oleh peserta pada tanggal 1 September 2024 pukul 17.00 WIB\n</p><p><br></p><p>\nSTAY TUNED WITH US🙌🏻\n</p><p><br></p><p>\nNarahubung:\n</p><p>📲 : Libitha (081382836964)\n</p><p>📲 : Melia (088214680464)\n\nUntuk informasi lebih lanjut mengenai PKKP 2024, pantau terus informasi resmi dari instagram kami!</p><p><br></p><p>Link Detail:&nbsp;<a href=\"https://s.pnj.ac.id/TwibbonDanKetentuan\" target=\"_blank\">FILE DRIVE</a>&nbsp;<a href=\"https://www.instagram.com/p/C_P-ZFBMKpK/\" target=\"_blank\">INSTAGRAM</a></p>', '<p><img src=\"/storage/files/images/WhatsApp_Image_2024-08-30_at_11.11.17_1725011264.jpeg\" class=\"img-fluid\" style=\"width: 540px;\"><br></p>', 'PKKP', 'Kuliah', 'Selesai', '2024-08-30 09:44:41', '2024-08-31 14:02:54'),
(7, '1', '2024-08-31', '2024-09-03', 'Tugas Individual II (VIDEO A DAY IN MY LIFE)', '<p>Tugas Individual II (VIDEO A DAY IN MY LIFE)</p><p><br></p><p>\n</p><p>1. Penugasan WAJIB bersifat individu </p><p>\n2. Peserta WAJIB membuat video a day in my life sekreatif mungkin.\n</p><p>3. Ketentuan Peserta :\nDimulai dari perkenalan diri (Nama, Jurusan, Angkatan, Prodi, Gugus) baru dimulai kegiatan selama di PNJ\nDurasi maksimal selama 2 menit\n</p><p>4. Video berisikan cuplikan kegiatan selama rangkaian PKKP di Politeknik Negeri Jakarta\n</p><p>5. Kegiatan selama di rindam tidak perlu didokumentasikan, jika ingin dimasukkan cukup ceritakan ceritakan secara singkat apa saja yang didapat selama di rindam.\n</p><p>6. Video di posting di TikTok dan Reels Instagram First Account dan akun tidak boleh privat </p><p>\n7. Wajib untuk tag akun Instagram @pkkp_pnj @politekniknegerijakarta dan TikTok @pkkp_pnj @pnjofficial_\n</p><p>8. Peserta dilarang menghapus video tersebut sampai tanggal 10 September 2024\n</p><p>9. Caption : \nIsi caption sekreatif mungkin dengan tambahan tagar #PKKP2024 #BerdayaUntukNegeriBerkaryaUntukMasaDepan #PoliteknikNegeriJakarta #JurusanKalian #NamaGugus\n</p><p><br></p><p>\nTujuan &amp; Manfaat : </p><p>- Melatih jiwa kreatifitas peserta khususnya dalam bidang editing\n</p><p>- Meningkatkan jiwa percaya diri melalui video yang diunggah di akun pribadi\n</p><p>- Meramaikan rangkaian acara PKKP 2024 ke khalayak umum\n</p><p>- Sebagai bentuk dokumentasi pribadi dan kebanggan tersendiri bahwa telah mengikuti serangkaian acara PKKP 2024\n</p><p><br></p><p>\nDEADLINE PENGUMPULAN :\n</p><p>GUGUS 1-18 : 3 SEPTEMBER 2024 PUKUL 22.00 WIB\n</p><p>GUGUS 19-36 : 7 SEPTEMBER 2024 PUKUL 12.00 WIB&nbsp;</p><p><br></p><p>Link Detail:&nbsp;<a href=\"https://s.pnj.ac.id/MissionADayInMyLife\" target=\"_blank\">FILE DRIVE</a>&nbsp;<a href=\"https://www.instagram.com/p/C_SB1x4zzJJ/?img_index=2\" target=\"_blank\">INSTAGRAM</a></p>', '<p>Link MISSION A DAY IN MY LIFE</p><p><br></p><p>Link IG:\n</p><p><a href=\"https://www.instagram.com/reel/C_dOPNHyw4t/?igsh=MjhkNHB2OWR0YzE2\" target=\"_blank\">https://www.instagram.com/reel/C_dOPNHyw4t/?igsh=MjhkNHB2OWR0YzE2</a><br></p><p><br></p><p>\nLink TikTok:\n</p><p><a href=\"https://vt.tiktok.com/ZS2Dgru2X/\" target=\"_blank\">https://vt.tiktok.com/ZS2Dgru2X/</a><br></p>', 'PKKP', 'Kuliah', 'Selesai', '2024-08-31 13:40:34', '2024-09-08 04:40:19'),
(8, '1', '2024-08-31', '2024-09-02', 'Tugas Individual III (Opinion on Day 1)', '<p>Tugas Individual III (Opinion on Day 1)</p><p><br></p><p>1. Penugasan WAJIB bersifat individu </p><p>\n2. Peserta WAJIB membuat video pendapat mengenai materi pada hari pertama secara kreatif dengan minimal durasi 1 menit\n</p><p>3. Untuk Opinion on Day 1, yang harus disertakan dalam video adalah sebagai berikut:\n</p><p>- Nama, Jurusan, Angkatan, Prodi, Gugus\nBebas memilih materi di Day 1 (Contoh Day 1: Materi 1,2,3, yang dipilih materi 2)\n</p><p>- Alasan memilih materi tersebut\n</p><p>- Kelebihan dan kekurangan  materi tersebut\n</p><p>- Nilai-nilai positif apa yang bisa diambil dan di implementasikan terhadap kehidupan kampus dan bermasyarakat\nArgumen dan pendapat pribadi terhadap materi tersebut&nbsp;</p><p>4. Ketentuan Peserta :\n</p><p>- Harus terlihat wajahnya\n</p><p>- Memakai kemeja putih\n</p><p>- Bagi laki-laki memakai celana hitam\n</p><p>- Bagi perempuan memakai rok hitam dan kerudung hitam (bagi yang menggunakan hijab)\n</p><p>- Rambut rapih</p><p>5. Video di posting di Reels Instagram First Account dan akun tidak boleh privat </p><p>6. Wajib untuk tag akun Instagram @pkkp_pnj @politekniknegerijakarta </p><p>7. Peserta dilarang menghapus video tersebut sampai tanggal 10 September 2024\n</p><p>8. Caption : \nIsi caption sekreatif mungkin dengan tambahan tagar #PKKP2024 #BerdayaUntukNegeriBerkaryaUntukMasaDepan #PoliteknikNegeriJakarta #JurusanKalian #NamaGugus #JudulMateri #TanggalMateri\n</p><p><br></p><p>\nTujuan &amp; Manfaat : </p><p>- Melatih public speaking, critical thinking dan kreatifitas</p><p>- Menambah wawasan terhadap kehidupan kampus</p><p>- Meramaikan pembukaan rangkaian acara PKKP 2024 ke khalayak umum</p><p>- Meningkatkan rasa kebanggaan terhadap kampus Politeknik Negeri Jakarta\n</p><p><br></p><p>DEADLINE : \nOPINION ON DAY 1\nGUGUS 1-18 : 2 SEPTEMBER 2024 PUKUL 22.00 WIB\nGUGUS 19-36 : 5  SEPTEMBER 2024 PUKUL 22.00 WIB&nbsp;</p><p><br></p><p>Link Detail:&nbsp;<a href=\"https://s.pnj.ac.id/MissionOpinionOnTheDayPKKP\" target=\"_blank\">FILE DRIVE</a>&nbsp;<a href=\"https://www.instagram.com/p/C_SDeeyz1O1/?img_index=2\" target=\"_blank\">INSTAGRAM</a></p>', '<p>Link IG:<br><br><a href=\"https://www.instagram.com/reel/C_aqA2vyYAj/?igsh=MXU1NHhiYWtuY3lueQ==\" target=\"_blank\">https://www.instagram.com/reel/C_aqA2vyYAj/?igsh=MXU1NHhiYWtuY3lueQ==</a><br></p>', 'PKKP', 'Kuliah', 'Selesai', '2024-08-31 13:48:23', '2024-09-02 14:04:58'),
(9, '1', '2024-08-31', '2024-09-04', 'Tugas Individual III (Day Gebyar Ormawa)', '<p>Tugas Individual III (Day Gebyar Ormawa)</p><p><br></p><p>1. Penugasan WAJIB bersifat individu\n</p><p>\n2. Peserta WAJIB membuat video pendapat mengenai materi pada hari pertama secara kreatif dengan minimal durasi 1 menit</p><p>3. Untuk Opinion on Day Gebyar Ormawa, yang harus disertakan dalam video adalah sebagai berikut:\n</p><p>- Nama, Jurusan, Angkatan, Prodi, Gugus\n</p><p>- Bebas memilih minimal 3 Ormawa pada saat Gebyar Ormawa </p><p>- Alasan memilih Ormawa tersebut\n</p><p>- Argumen dan pendapat pribadi terhadap ormawa tersebut&nbsp;</p><p>4. Ketentuan Peserta :</p><p>\n\n- Harus terlihat wajahnya\n</p><p>\n- Memakai kemeja putih\n</p><p>\n- Bagi laki-laki memakai celana hitam</p><p>\n\n- Bagi perempuan memakai rok hitam dan kerudung hitam (bagi yang menggunakan hijab)</p><p>\n\n- Rambut rapih\n</p><p>\n\n\n5. Video di posting di Reels Instagram First Account dan akun tidak boleh privat\n</p><p>\n6. Wajib untuk tag akun Instagram @pkkp_pnj @politekniknegerijakarta\n</p><p>\n7. Peserta dilarang menghapus video tersebut sampai tanggal 10 September 2024\n</p><p>\n8. Caption : Isi caption sekreatif mungkin dengan tambahan tagar #PKKP2024 #BerdayaUntukNegeriBerkaryaUntukMasaDepan #PoliteknikNegeriJakarta #JurusanKalian #NamaGugus #JudulMateri #TanggalMateri\n</p><p><br></p><p>\n\n\nTujuan &amp; Manfaat :\n</p><p>\n- Melatih public speaking, critical thinking dan kreatifitas\n</p><p>\n- Menambah wawasan terhadap kehidupan kampus\n</p><p>\n- Meramaikan pembukaan rangkaian acara PKKP 2024 ke khalayak umum</p><p>\n\n- Meningkatkan rasa kebanggaan terhadap kampus Politeknik Negeri Jakarta\n</p><p><br></p><p>\n\n\nDEADLINE :&nbsp;<span style=\"letter-spacing: 0.05em;\">OPINION ON DAY GEBYAR ORMAWA\n</span></p><p><span style=\"letter-spacing: 0.05em;\">GUGUS 1-18 : 4 SEPTEMBER 2024 PUKUL 22.00 WIB\n</span></p><p><span style=\"letter-spacing: 0.05em;\">GUGUS 19-36 : 6 SEPTEMBER 2024 PUKUL 22.00 WIB</span><br></p><p><br></p><p>Link Detail:&nbsp;<a href=\"https://s.pnj.ac.id/MissionOpinionOnTheDayPKKP\" target=\"_blank\">FILE DRIVE</a>&nbsp;<a href=\"https://www.instagram.com/p/C_SDeeyz1O1/?img_index=1\" target=\"_blank\">INSTAGRAM</a></p>', '<p>Tugas GEBYAR ORMAWA:</p><p><br></p><p>Link IG:</p><p><a href=\"https://www.instagram.com/reel/C_f3czzysHA/?igsh=MTJxeTljOWtieWhqcg==\" target=\"_blank\">https://www.instagram.com/reel/C_f3czzysHA/?igsh=MTJxeTljOWtieWhqcg==</a><br></p>', 'PKKP', 'Kuliah', 'Selesai', '2024-08-31 14:11:14', '2024-09-08 04:41:20'),
(10, '1', '2024-08-31', '2024-09-07', '[Group Task: Yel-Yel Gugus]', '<p>GROUP TASK : YEL - YEL GUGUS\n</p><p><br></p><p>Ketentuan Yel - Yel Gugus</p><p>\n</p><p>1. Penugasan WAJIB bersifat grup/gugus.\n</p><p>2. Peserta WAJIB membuat video yel-yel secara kreatif (dari Rindam Jaya) dengan minimal durasi 1 menit dan maksimal 2 menit dengan menyertakan:\n</p><p>- Nama Gugus\n</p><p>- Yel-yel&nbsp;<span style=\"letter-spacing: 0.05em;\">tidak mengandung SARA\n</span></p><p><span style=\"letter-spacing: 0.05em;\">- Harapan untuk PNJ\n</span></p><p><span style=\"letter-spacing: 0.05em;\">3. Ketentuan Peserta:\n</span></p><p><span style=\"letter-spacing: 0.05em;\">- Memakai kemeja putih\n</span></p><p><span style=\"letter-spacing: 0.05em;\">- Bagi laki-laki memakai celana hitam\n</span></p><p><span style=\"letter-spacing: 0.05em;\">- Bagi perempuan memakai rok hitam dan kerudung hitam (bagi yang berhijab)\n</span></p><p><span style=\"letter-spacing: 0.05em;\">- Ramput rapih sesuai ketentuan\n</span></p><p><span style=\"letter-spacing: 0.05em;\">4. Video wajib di posting di TikTok dan Reels Instagram First Account dan akun tidak boleh privat\n(Video hanya diposting oleh salah satu anggota kelompok, tidak perlu semua anggota mengupload)\n</span></p><p><span style=\"letter-spacing: 0.05em;\">5. Wajib untuk tag akun Instagram @pkkp_pnj @politekniknegerijakarta dan TikTok @pkkp_pnj @pnjofficial_\n</span></p><p><span style=\"letter-spacing: 0.05em;\">6. Peserta dilarang menghapus video tersebut sampai tanggal 10 September 2024\n</span></p><p><span style=\"letter-spacing: 0.05em;\">7. Empat gugus dengan yel-yel paling kreatif dan semangat akan di posting pada Instagram dan Tiktok PKKP PNJ\n</span></p><p><span style=\"letter-spacing: 0.05em;\">8. Caption : </span></p><p><span style=\"letter-spacing: 0.05em;\">\nIsi caption sekreatif mungkin dengan tambahan tagar #PKKP2024 #BerdayaUntukNegeriBerkaryaUntukMasaDepan #PoliteknikNegeriJakarta #JurusanKalian #NamaGugus\n</span></p><p><span style=\"letter-spacing: 0.05em;\"><br></span></p><p><span style=\"letter-spacing: 0.05em;\">\nDEADLINE PENGUMPULAN\n</span></p><p><span style=\"letter-spacing: 0.05em;\">Gugus 1-18 : 7 SEPTEMBER 2024 PUKUL 16.00\n</span></p><p><span style=\"letter-spacing: 0.05em;\">Gugus 19-36 : 4 SEPTEMBER 2024 PUKUL 16.00&nbsp;</span></p><p><span style=\"letter-spacing: 0.05em;\"><br></span></p><p><span style=\"letter-spacing: 0.05em;\">Link Detail:&nbsp;</span><a href=\"https://s.pnj.ac.id/MissionGroupTask\" target=\"_blank\">FILE DRIVE</a><span style=\"letter-spacing: 0.05em;\">&nbsp;</span><a href=\"https://www.instagram.com/p/C_SGx79uNxO/?img_index=1\" target=\"_blank\">INSTAGRAM</a><span style=\"letter-spacing: 0.05em;\"><br></span><br></p>', '<p>Link Tugas Group: Yel-Yel\n</p><p><br></p><p>I<span style=\"letter-spacing: 0.05em;\">nstagram:\n</span></p><p><a href=\"https://www.instagram.com/reel/C_mx0IlRmWZ/?igsh=MXJlamJjaXE0OHRmZA==\" target=\"_blank\">https://www.instagram.com/reel/C_mx0IlRmWZ/?igsh=MXJlamJjaXE0OHRmZA==</a><br></p><p><span style=\"letter-spacing: 0.05em;\"><br></span></p><p><span style=\"letter-spacing: 0.05em;\">Tiktok:\n</span></p><p><a href=\"https://vt.tiktok.com/ZS2fAr588/\" target=\"_blank\">https://vt.tiktok.com/ZS2fAr588/</a><br></p>', 'PKKP', 'Kuliah', 'Selesai', '2024-08-31 14:17:36', '2024-09-08 04:38:41'),
(11, '2', '2024-09-11', '2024-09-11', '[G-Form] PRE TEST 1 MK AGAMA ISLAM', '<p>PRE TEST 1 MK AGAMA ISLAM</p><p><br></p><p>--</p><p>Link:</p><p><a href=\"https://elearning.pnj.ac.id/mod/assign/view.php?id=533245\" target=\"_blank\">https://elearning.pnj.ac.id/mod/assign/view.php?id=533245</a><a href=\"https://elearning.pnj.ac.id/mod/assign/view.php?id=533245\" target=\"_blank\"></a></p><p><a href=\"https://drive.google.com/file/d/1c-TZ-dX3NtpTigqT34QHgihQNQ01QmL_/view?usp=sharing\" target=\"_blank\">https://drive.google.com/file/d/1c-TZ-dX3NtpTigqT34QHgihQNQ01QmL_/view?usp=sharing</a><br><br></p>', '<p>PRE TEST 1 MK AGAMA ISLAM</p><p><br></p><p>--</p><p>Link Jawaban:</p><p><a href=\"https://drive.google.com/file/d/171k6fmdsY0XQI9dp3NvqnlyoRMfdDbEt/view?usp=sharing\" target=\"_blank\">https://drive.google.com/file/d/171k6fmdsY0XQI9dp3NvqnlyoRMfdDbEt/view?usp=sharing</a><br></p>', 'Tugas', 'Kuliah', 'Selesai', '2024-09-11 06:18:28', '2024-09-29 22:36:02'),
(12, '11', '2024-09-16', '2024-09-16', '[Kumpulin] Tugas Rev (1) ', '<p>Tugas Rev (1) - Pengukuran Listrik</p><p><br></p><p>1. Jawablah soal-soal berikut:</p><ul style=\"list-style-type: lower-alpha;\"><li><p>Apa yang dimaksud dengan pengukuran dan sebutkan unsur yang perlu diperhatikan\ndalam pengukuran, jelaskan</p></li><li><p>Apa yang dimaksud dengan besaran, satuan, dan dimensi. Jelaskan klasifikasinya!</p></li><li><p>Sebutkan pembagian alat ukur menurut nilai hasil ukur, menurut prinsip kerja, dan\nmenurut besaran yang diukur</p></li></ul><p>2. Jawablah soal-soal berikut:</p><ul style=\"list-style-type: lower-alpha;\"><li><p>Sebutkan dan jelaskan karakteristik alat ukur</p></li><li><p>Jarum penunjuk pada angka 18, skala maksimum 30, batas ukur pada angka 12V\nBerapa harga pengukuran sebenarnya?</p></li><li>Jika Voltmeter dengan kepekaan 20kΩ/V digunakan pada pengukuran seperti Gbr1,\nberapakah drop tegangan pada R1 yang sebenarnya?<br><img src=\"/storage/files/images/Screenshot_from_2024-09-21_18-54-30_1726919684.png\" class=\"img-fluid\" style=\"width: 218px;\"></li></ul><p>3.&nbsp;<span style=\"letter-spacing: 0.05em;\">Sebutkan 6 hal yang perlu diperhatikan dalam pengukuran, dan Sebutkan 3 Jenis Kesalahan</span></p><p><span style=\"letter-spacing: 0.05em;\">4.&nbsp;</span><span style=\"letter-spacing: 0.05em;\">Suatu rentetan pengukuran tegangan yg tidak saling bergantungan (independen) dilakukan\noleh enam pengamat dan menghasilkan 12,9V; 12,3V; 12,6V; 13,2V; 13V dan 12,5V.\nTentukan: Nilai rata2, Deviasi, Rata2 deviasi, Standar deviasi, Variansi, Probable error.</span></p><p><span style=\"letter-spacing: 0.05em;\">5. Jawablah soal-soal berikut:</span></p><ul style=\"list-style-type: lower-alpha;\"><li><p>Bagaimana Teknik pengukuan arus dan pengukuran tegangan pada suatu rangkaian</p></li><li><p>Jika ingin mengetahui harga tahanan Rx yang besar sesuai hukum ohm dengan\npengukuran tegangan dan arus, bagaimana konfigurasi rangkaian pengukurannya?\nJelaskan alasannya</p></li></ul><p><span style=\"letter-spacing: 0.05em;\">6.&nbsp;</span><span style=\"letter-spacing: 0.05em;\">Data alat ukur kumparan putar dengan dimensi 31/2 in, arus 1 mA, simpangan skala\npenuh 100 derajat memiliki A: 1,70 cm2, B: 1.800 G (0,2 Wb/m2, N: 80 lilit, Hitunglah\ntorsi putar pada jarum penunjuk.</span></p><p><span style=\"letter-spacing: 0.05em;\">7.&nbsp;</span><span style=\"letter-spacing: 0.05em;\">KWh-meter satu phasa memiliki konstanta putaran 600 putaran/kWh dalam waktu 2\nmenit tercatat 80 putaran piringan. Hitunglah beban daya listrik?</span></p><p><span style=\"letter-spacing: 0.05em;\">8.&nbsp;</span><span style=\"letter-spacing: 0.05em;\">Gambarkan skematik pengawatan pengukuran Kwh meter 3 phasa dengan menggunakan\ntiga buah trafo arus (CT) 200 A/5 A. Jelaskan cara kerja pengukuran tersebut.</span></p><p><span style=\"letter-spacing: 0.05em;\">9.&nbsp;</span><span style=\"letter-spacing: 0.05em;\">Pengukur tegangan voltmeter memiliki arus meter 0,5mA, tegangan meter 0,25V.\nVoltmeter digunakan untuk mengukur tegangan 2,5V. Hit besar tahanan seri meter Rv</span></p><p><span style=\"letter-spacing: 0.05em;\">10.&nbsp;</span><span style=\"letter-spacing: 0.05em;\">Ampermeter dengan tahanan dalam Rm =200 ohm, arus yg diizinkan melewati meter Im =\n0,5 mA. Ampermeter akan mengukur arus I = 10 mA. Hitung tahanan paralel Rp</span></p><p><span style=\"letter-spacing: 0.05em;\">11.&nbsp;</span><span style=\"letter-spacing: 0.05em;\">Jembatan Wheatstone, diketahui besarnya nilai R 2\n\n=400Ω, R 3\n\n= 250Ω , R4\n=500 Ω\n\nHitung besarnya R1\n\ndalam kondisi setimbang.</span></p><p><span style=\"letter-spacing: 0.05em;\">12.&nbsp;</span><span style=\"letter-spacing: 0.05em;\">Gambarkan skematik pengukuran tegangan AC menggunakan osiloskop, jelaskan urutan\ncara pengoperasiannya.</span></p><p><span style=\"letter-spacing: 0.05em;\">13.&nbsp;</span><span style=\"letter-spacing: 0.05em;\">Carilah Simbol, Persamaan, dan Satuan dari: Muatan Listrik, Kuat medan Listrik, Kuat\nmedan magnet, Kerapatan flux magnet, Permitivitas, Permeabilitas</span></p><p><span style=\"letter-spacing: 0.05em;\">14.&nbsp;</span><span style=\"letter-spacing: 0.05em;\">Buatkan 5 buah soal pilihan berganda dengan jawaban nya</span></p>', '<p>Link Jawaban :</p><p><a href=\"https://drive.google.com/file/d/1NuW21m9yKM3759Zyhn7IiisNMBr4JgqW/view?usp=sharing\" target=\"_blank\">https://drive.google.com/file/d/1NuW21m9yKM3759Zyhn7IiisNMBr4JgqW/view?usp=sharing</a><br></p>', 'Tugas', 'Kuliah', 'Selesai', '2024-09-21 11:51:52', '2024-09-29 22:35:54'),
(13, '9', '2024-09-17', '2024-09-17', '[Kumpulin] Algoritma Memindahkan Robot Lengan', '<p>Buatkan algoritma untuk memindahkan robot lengan dari kanan ke kiri</p>', '<p>1. Siapkan Alat dan Bahan</p><p>2. Hubungkan arduino nano ke laptop untuk memulai program</p><p>3. Buka IDE Arduino:</p><p>Memprogram:</p><ol><li style=\"line-height: 1;\">Include library servo</li><li style=\"line-height: 1;\">Inisialisasi Variabel dan Inisialisasi servo di void setup</li><li style=\"line-height: 1;\">Program servo 1 sebagai rotasi (kanan-kiri), arahkan ke objek</li><li style=\"line-height: 1;\">Program servo 2 sebagai tuas (atas-bawah), turunkan ke objek</li><li style=\"line-height: 1;\">Program servo 3 sebagai pencapit, capitkan ke objek</li><li style=\"line-height: 1;\">Program servo 2, angkat objek ke atas</li><li style=\"line-height: 1;\">Program servo 1, arahkan ke kiri 180 derajat untuk memindahkan dari kanan ke kiri</li><li style=\"line-height: 1;\">Program servo 2, turunkan objek ke bawah untuk menaruh</li><li style=\"line-height: 1;\">Program servo 3, lepaskan capitan dari objek</li></ol>', 'Tugas', 'Kuliah', 'Selesai', '2024-09-21 12:00:00', '2024-09-29 22:35:37'),
(14, '3', '2024-09-17', '2024-09-17', '[Kelompok] Tugas Sejarah Perjalanan Pancasila Pra Kemerdekaan', '<p>Tugas 1 – Sejarah Perjalanan Pancasila Pra Kemerdekaan\nKetentuan:</p><p>\n</p><p>1. Buatlah Presentasi dengan Judul Sejarah Perjalanan Pancasila Pra kemerdekaan\n</p><p>2. Prsentasi dibuat dalam bentuk PPT\n</p><p>3. Buatlah Presentasi semenarik mungkin dan jika perlu ditambahkan gambar/foto\n</p><p>4. PPT dibuat dengan jumlah 7 halaman\n</p><p>5. Dihalaman terakhir tuliskan sumber/referensi tulisan ( Tidak Boleh Wikipedia/Blogspot)\n</p><p>6. PPT dibuat secara kelompok ( jumlah orang dalam kelompok disesuaikan untuk 4\nkelompol(dan disubmit di elearning sesuai dengan waktu kuliah berakhir</p><p><br></p><p>Bahasan untuk kelompok : </p><p>1. Era Kerajaan\n</p><p>2. BPUPKI\n</p><p>3. PPKI\n</p><p>4. Piagam Jakarta hingga proklamasi kemerdekaan</p>', '<p>Link Jawaban PPT - Kelompok 3:</p><p><a href=\"https://docs.google.com/presentation/d/1OJ58RXAO1BoDuar1aTRfBWqjw4Q3lmmT/edit?usp=drive_link&amp;ouid=111247098934802644521&amp;rtpof=true&amp;sd=true\" target=\"_blank\">https://docs.google.com/presentation/d/1OJ58RXAO1BoDuar1aTRfBWqjw4Q3lmmT/edit?usp=drive_link&amp;ouid=111247098934802644521&amp;rtpof=true&amp;sd=true</a><br></p><p><br></p>', 'Tugas', 'Kuliah', 'Selesai', '2024-09-21 12:01:28', '2024-09-29 22:35:45');
INSERT INTO `tugas` (`id`, `id_matkul`, `tgl`, `tgl_deadline`, `judul_tugas`, `deskripsi`, `jawaban`, `kategori`, `tipe`, `status`, `created_at`, `updated_at`) VALUES
